const state={role:null,user:null,page:'dashboard',dashboardPeriod:'current_month',dashboardBranch:'Todas las sedes',dashboardDoctor:'Todos los médicos',pageState:{}};
function can(page){return !!state.role&&(perms[state.role]||[]).includes(page)}
function actionAllowed(action){return !actionRoles[action]||(actionRoles[action]||[]).includes(state.role)}
function userBranch(){return state.user?.branch||'Todas las sedes'}
function scopeBranch(rows,field='branch',requested='Todas las sedes'){const forced=['gerencia','sistemas'].includes(state.role)?requested:userBranch();return forced==='Todas las sedes'?rows:rows.filter(x=>x[field]===forced)}
