function closeModal(){$('#modalRoot').innerHTML=''}
function modal(content,small=false){$('#modalRoot').innerHTML=`<div class="overlay"><div class="modal ${small?'small':''}"><button class="close" data-action="close-modal">×</button>${content}</div></div>`}
function nextCode(prefix,arr,key,start=1,width=6){let max=start-1;arr.forEach(x=>{const m=String(x[key]||'').match(/(\d+)$/);if(m)max=Math.max(max,+m[1])});return `${prefix}-${String(max+1).padStart(width,'0')}`}
function periodMatch(dateStr,period){if(period==='all')return true;const d=new Date(dateStr+'T12:00:00-05:00');if(period==='current_month')return d.getFullYear()===2026&&d.getMonth()===9;if(period==='prev_month')return d.getFullYear()===2026&&d.getMonth()===8;if(period==='year_2026')return d.getFullYear()===2026;if(period==='year_2025')return d.getFullYear()===2025;return true}
function money(n){return `S/ ${Number(n).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function rowTable(headers,rows){return `<div class="tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Sin resultados para los filtros seleccionados.</td></tr>`}</tbody></table></div>`}
function pagedTable(headers,rows,key='default',pageSize=25){const current=Math.max(1,state.pageState[key]||1),pages=Math.max(1,Math.ceil(rows.length/pageSize)),page=Math.min(current,pages);state.pageState[key]=page;const start=(page-1)*pageSize;return `${rowTable(headers,rows.slice(start,start+pageSize))}<div class="pager"><span>${rows.length.toLocaleString('es-PE')} registros · Página ${page} de ${pages}</span><button class="btn btn-outline btn-sm" data-page-key="${key}" data-page-delta="-1" ${page<=1?'disabled':''}>Anterior</button><button class="btn btn-outline btn-sm" data-page-key="${key}" data-page-delta="1" ${page>=pages?'disabled':''}>Siguiente</button></div>`}
function workStatusBadge(s){const cls=s==='Activo'?'ok':s==='Vacaciones'||s==='Licencia'?'warn':s==='Baja'?'danger':'neutral';return `<span class="badge ${cls}">${s}</span>`}
function workPeriod(s){if(!s.statusFrom&&!s.statusUntil)return '—';if(s.statusFrom&&s.statusUntil)return `${s.statusFrom} → ${s.statusUntil}`;return `Desde ${s.statusFrom||'—'}`}
function staffSchedule(s){return `${s.workDays||'Lun–Sáb'} · ${s.shiftStart||'—'}–${s.shiftEnd||'—'}`}
function renderBranchesPublic(){$('#branchCards').innerHTML=branches.map(b=>`<div class="card"><span class="badge">${b.code}</span><h3>Nova Salud ${b.name}</h3><p>${b.address}</p><p>${b.phone}</p><p><b>Consultas:</b> ${b.consultHours}<br><b>Farmacia:</b> ${b.pharmacyHours}<br><b>Emergencia:</b> ${b.emergencyHours}</p><button class="btn btn-soft btn-sm" data-action="book">Solicitar cita aquí</button></div>`).join('')}
function renderFeaturedSpecialists(){document.querySelectorAll('[data-feature-specialty]').forEach(box=>{const specialty=box.dataset.featureSpecialty;const doc=demo.staff.find(x=>x.role==='Médico'&&x.workStatus==='Activo'&&x.specialty===specialty);if(!doc){box.innerHTML='<small>Especialista disponible según sede y horario.</small>';return}box.innerHTML=`<b>${doc.name}</b><small>${doc.specialty} · ${doc.branch} · ${staffSchedule(doc)}</small>`})}
function renderPublicSpecialists(){const sel=$('#publicSpecialistBranch'),grid=$('#publicSpecialistGrid');if(!sel||!grid)return;if(sel.options.length===1)branches.forEach(b=>sel.insertAdjacentHTML('beforeend',`<option>${b.name}</option>`));const update=()=>{const branch=sel.value;let rows=demo.staff.filter(x=>x.role==='Médico'&&x.workStatus==='Activo'&&(branch==='Todas las sedes'||x.branch===branch));rows=rows.slice(0,9);grid.innerHTML=rows.length?rows.map(x=>`<div class="card doctor-card"><span class="badge ok">Disponible</span><h3>${x.name}</h3><div class="doctor-meta"><span class="badge blue">${x.specialty}</span><span class="badge">${x.branch}</span></div><div class="doctor-hours">🕒 ${staffSchedule(x)}</div><button class="btn btn-soft btn-sm" data-action="book">Solicitar cita</button></div>`).join(''):'<div class="notice">No hay especialistas activos para la sede seleccionada en esta demostración.</div>'};sel.onchange=update;update()}
function openPolicy(kind){const contents={privacy:`<span class="eyebrow">Protección de datos</span><h2>Política de Privacidad · Demo académica</h2><div class="privacy"><p>Clínica Nova Salud es un prototipo académico. Los datos usados en esta demostración son ficticios. En una implementación real, la clínica debe informar de manera clara la identidad del responsable del tratamiento, las finalidades, destinatarios, transferencias, conservación, mecanismos para ejercer derechos y demás información exigible.</p><h3>Datos que podría tratar la clínica</h3><ul><li>Identificación y contacto.</li><li>Información de citas, pagos, seguros y facturación.</li><li>Datos de salud e historial clínico, considerados especialmente sensibles.</li><li>Registros técnicos de acceso y auditoría.</li></ul><h3>Finalidades</h3><p>Gestionar atención, citas, historial, farmacia, pagos, seguridad, soporte y obligaciones legales. El uso comercial debe mantenerse separado y ser opcional.</p><h3>Seguridad y acceso</h3><p>El sistema aplica roles y trazabilidad. Cada perfil debe acceder únicamente a la información necesaria para su función.</p><p class="hint">Referencia académica: Ley N.º 29733 y Reglamento aprobado por D.S. N.º 016-2024-JUS. Para una clínica real, el texto final debe ser revisado legalmente.</p></div>`,arco:`<span class="eyebrow">Tus derechos</span><h2>Derechos ARCO</h2><div class="privacy"><p>El titular puede solicitar Acceso, Rectificación, Cancelación u Oposición respecto de sus datos personales, conforme al marco peruano de protección de datos.</p><ul><li><b>Acceso:</b> conocer qué datos se tratan y para qué.</li><li><b>Rectificación:</b> corregir datos inexactos o incompletos.</li><li><b>Cancelación:</b> solicitar la supresión cuando corresponda.</li><li><b>Oposición:</b> oponerse a determinados tratamientos cuando resulte aplicable.</li></ul><p>En esta demo el canal es <b>privacidad@novasalud.demo</b>. No procesa solicitudes reales.</p></div>`,cookies:`<span class="eyebrow">Navegación</span><h2>Política de Cookies · Demo</h2><div class="privacy"><p>Esta versión funciona localmente y no instala cookies publicitarias. En una publicación real, Nova Salud debería informar y gestionar preferencias para cookies no esenciales, analítica y servicios externos.</p></div>`,terms:`<span class="eyebrow">Uso del prototipo</span><h2>Términos y condiciones</h2><div class="privacy"><p>Este sitio es una demostración académica. No presta servicios médicos reales, no emite comprobantes tributarios reales y no debe utilizarse para almacenar información verdadera de pacientes.</p></div>`};modal(contents[kind]||contents.privacy,true)}
function openPatientModal(mode='register'){modal(`<span class="eyebrow">Portal del paciente</span><h2>Accede a Nova Salud</h2><p class="muted">Crea tu cuenta para solicitar citas y consultar tu información.</p><div class="tabs"><button class="tab ${mode==='register'?'active':''}" data-patient-tab="register">Crear cuenta</button><button class="tab ${mode==='login'?'active':''}" data-patient-tab="login">Ya tengo cuenta</button></div><div id="patientAuthBody"></div>`);renderPatientAuth(mode)}
function renderPatientAuth(mode){const body=$('#patientAuthBody');if(mode==='login'){body.innerHTML=`<form id="patientLogin"><div class="formgrid"><label>DNI<input name="dni" maxlength="8" autocomplete="username" placeholder="8 dígitos" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required></label></div><div style="margin-top:16px"><button class="btn btn-primary">Ingresar a mi portal</button></div></form>`;return}body.innerHTML=`<form id="patientRegister"><div class="notice">Tu <b>cuenta se crea de inmediato</b> y podrás entrar al portal con la contraseña que elijas. La ficha clínica quedará <b>pendiente de validación</b> por Recepción antes de habilitar funciones clínicas sensibles.</div><section class="formsec"><h3>1. Datos de acceso</h3><div class="formgrid"><label>Correo electrónico<input name="email" type="email" required></label><label>Contraseña<input name="password" type="password" minlength="8" autocomplete="new-password" required></label></div></section><section class="formsec"><h3>2. Identificación</h3><div class="formgrid three"><label>DNI<input name="dni" maxlength="8" pattern="[0-9]{8}" required></label><label>Nombres<input name="first" required></label><label>Apellidos<input name="last" required></label><label>Fecha de nacimiento<input name="birth" type="date" required></label><label>Teléfono<input name="phone" required></label><label>Sede preferida<select name="branch">${branchOptions()}</select></label></div></section><section class="formsec"><h3>3. Contacto y cobertura</h3><div class="formgrid"><label>Dirección<input name="address" required></label><label>Distrito<input name="district" required></label><label>Seguro<select name="insurance"><option>Particular</option><option>SIS</option><option>Rímac</option><option>Pacífico</option><option>Mapfre</option></select></label><label>N.º de póliza / afiliación<input name="policy" placeholder="Opcional"></label><label>Contacto de emergencia<input name="emergencyName"></label><label>Teléfono de emergencia<input name="emergencyPhone"></label></div></section><section class="formsec"><h3>4. Privacidad y consentimiento</h3><label class="check"><input name="privacyConsent" type="checkbox" required> He leído la Política de Privacidad y autorizo el tratamiento necesario para gestionar mi cuenta, citas y atención.</label><details class="notice"><summary><b>Ver resumen de privacidad</b></summary><p>Los datos del prototipo se usan para gestionar cuenta, citas, atención, pagos y seguridad. Los datos de salud requieren especial protección. El consentimiento comercial es independiente y opcional. Esta demo usa únicamente datos ficticios.</p></details><label class="check"><input name="healthConsent" type="checkbox" required> Autorizo el tratamiento de datos de salud para la prestación y gestión de mis atenciones dentro de este prototipo.</label><label class="check"><input name="marketingConsent" type="checkbox"> Deseo recibir promociones y novedades. <b>(Opcional)</b></label></section><button class="btn btn-primary">Crear cuenta e ingresar</button></form>`}
function openStaffLogin(){modal(`<span class="eyebrow">Acceso interno</span><h2>Personal de Nova Salud</h2><p class="muted">Ingresa con el correo y la contraseña asignados. El sistema identifica automáticamente tu rol y sede.</p><form id="staffLogin"><div class="formgrid"><label>Correo<input name="email" type="email" autocomplete="username" placeholder="correo@novasalud.demo" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required></label></div><div class="notice" style="margin-top:14px">Las credenciales de demostración se entregan en un archivo separado y nunca se muestran dentro del sistema.</div><button class="btn btn-primary" style="margin-top:16px">Ingresar al sistema</button></form>`,true)}
function renderPatientSide(){const items=[['patient-home','⌂','Inicio'],['patient-appointments','📅','Mis citas'],['patient-profile','👤','Mi perfil'],['patient-payments','💳','Mis pagos']];$('#sideNav').innerHTML=items.map(([k,i,l])=>`<button class="navbtn ${state.page===k?'active':''}" data-page="${k}"><span>${i}</span><span>${l}</span></button>`).join('')}
function patientPortal(patient){closeModal();state.role='patient';state.user={code:patient.code,name:patient.name,branch:patient.branch,patient};state.page='patient-home';$('#publicView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#profileName').textContent=patient.name;$('#profileRole').textContent='Portal del paciente';$('#sessionScope').textContent=patient.branch;renderPatientSide();renderPatientHome()}
function renderPatientHome(){const p=state.user.patient,appts=demo.appointments.filter(a=>a.patientCode===p.code).sort((a,b)=>a.date.localeCompare(b.date)),next=appts.find(a=>a.date>=isoDate(DEMO_TODAY)&&!['Cancelada','Realizada'].includes(a.status));state.page='patient-home';$('#pageTitle').textContent='Mi salud';$('#pageKicker').textContent='Portal del paciente';$('#appContent').innerHTML=`${p.status==='Pendiente'?'<div class="notice" style="margin-bottom:14px"><b>Cuenta de portal creada · validación de paciente pendiente.</b> Ya puedes usar tu portal y solicitar citas. Recepción debe validar tu identidad antes de habilitar funciones clínicas sensibles.</div>':''}<div class="kpis"><div class="kpi"><span>Próxima cita</span><strong>${next?next.date.slice(5):'Sin cita'}</strong></div><div class="kpi"><span>Citas realizadas</span><strong>${appts.filter(a=>a.status==='Realizada').length}</strong></div><div class="kpi"><span>Pagos registrados</span><strong>${demo.invoices.filter(i=>i.patientCode===p.code).length}</strong></div><div class="kpi"><span>Sede preferida</span><strong style="font-size:1.2rem">${p.branch}</strong></div></div><div class="modulegrid" style="margin-top:14px"><div class="panel"><h3>Próxima atención</h3><p>${next?`<b>${next.doctor}</b></p><p class="muted">${next.date} · ${next.time} · ${next.branch}`:'<span class="muted">No tienes citas futuras registradas.</span>'}</p></div><div class="panel"><h3>Acciones rápidas</h3><div class="quick"><button data-action="patient-book"><span>📅</span><b>Solicitar cita</b></button><button data-page="patient-profile"><span>👤</span><b>Actualizar perfil</b></button><button data-page="patient-payments"><span>💳</span><b>Ver pagos</b></button></div></div></div>`;renderPatientSide()}
function openInternal(account){closeModal();state.role=account.role;state.user=account;state.page='dashboard';state.dashboardBranch=['gerencia','sistemas'].includes(account.role)?'Todas las sedes':account.branch;state.dashboardDoctor=account.role==='medico'?account.staffCode:'Todos los médicos';$('#publicView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#profileName').textContent=account.name;$('#profileRole').textContent=`${roles[account.role]} · ${account.branch}`;$('#sessionScope').textContent=['gerencia','sistemas'].includes(account.role)?'Acceso global':account.branch;renderNav();go('dashboard')}
function renderNav(){const allowed=perms[state.role]||[];$('#sideNav').innerHTML=nav.filter(x=>allowed.includes(x[0])).map(([k,i,l])=>`<button class="navbtn ${state.page===k?'active':''}" data-page="${k}"><span>${i}</span><span>${l}</span></button>`).join('')}
function dashboardData(){let branch=state.dashboardBranch;if(!['gerencia','sistemas'].includes(state.role))branch=userBranch();let appts=demo.appointments.filter(a=>periodMatch(a.date,state.dashboardPeriod));let inv=demo.invoices.filter(i=>periodMatch(i.date,state.dashboardPeriod));let pats=demo.patients.filter(p=>periodMatch(p.registered,state.dashboardPeriod));let mov=demo.movements.filter(m=>periodMatch(m.date,state.dashboardPeriod));if(branch!=='Todas las sedes'){appts=appts.filter(a=>a.branch===branch);inv=inv.filter(i=>i.branch===branch);pats=pats.filter(p=>p.branch===branch);mov=mov.filter(m=>m.branch===branch)}if(state.dashboardDoctor!=='Todos los médicos'){appts=appts.filter(a=>a.doctorCode===state.dashboardDoctor)}if(state.role==='medico'){appts=appts.filter(a=>a.doctorCode===state.user.staffCode)}return {branch,appts,inv,pats,mov}}
function dashboardMetrics(){const d=dashboardData(),critical=scopeBranch(demo.stock,'branch',d.branch).filter(s=>s.qty<=s.min).length,revenue=d.inv.filter(i=>i.status==='Pagado').reduce((s,i)=>s+i.total,0);if(state.role==='caja')return [['Ingresos del periodo',money(revenue)],['Comprobantes',d.inv.length.toLocaleString('es-PE')],['Pendientes',d.inv.filter(i=>i.status==='Pendiente').length],['Ticket promedio',money(d.inv.length?revenue/d.inv.length:0)]];if(state.role==='almacen')return [['Productos',demo.products.length],['Stock crítico',critical],['Movimientos',d.mov.length.toLocaleString('es-PE')],['Almacenes',scopeBranch(warehouses,'branch',d.branch).length]];if(state.role==='recepcion')return [['Pacientes registrados',d.pats.length.toLocaleString('es-PE')],['Citas',d.appts.length.toLocaleString('es-PE')],['Por confirmar',d.appts.filter(a=>a.status==='Programada').length],['Canceladas',d.appts.filter(a=>a.status==='Cancelada').length]];if(state.role==='medico')return [['Mis citas',d.appts.length],['Realizadas',d.appts.filter(a=>a.status==='Realizada').length],['Confirmadas',d.appts.filter(a=>a.status==='Confirmada').length],['Historias clínicas',demo.histories.filter(h=>h.doctorCode===state.user.staffCode&&periodMatch(h.date,state.dashboardPeriod)).length]];if(state.role==='enfermeria')return [['Citas de sede',d.appts.length],['Realizadas',d.appts.filter(a=>a.status==='Realizada').length],['Total de pacientes activos',scopeBranch(demo.patients,'branch',d.branch).filter(p=>p.status==='Activo').length.toLocaleString('es-PE')],['Sede',d.branch]];if(state.role==='sistemas')return [['Usuarios demo',demo.accounts.length],['Auditorías',demo.audit.length],['Tickets abiertos',demo.support.filter(s=>s.status==='Abierto').length],['Sedes','5']];return [['Pacientes registrados',d.pats.length.toLocaleString('es-PE')],['Citas del periodo',d.appts.length.toLocaleString('es-PE')],['Ingresos',money(revenue)],['Stock crítico',critical]]}
function dashboardSeries(){const d=dashboardData(),months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];let values=Array(12).fill(0);if(state.role==='caja'||state.role==='gerencia'){d.inv.forEach(x=>{const dt=new Date(x.date+'T12:00:00');values[dt.getMonth()]+=x.status==='Pagado'?x.total:0})}else if(state.role==='almacen'){d.mov.forEach(x=>{const dt=new Date(x.date+'T12:00:00');values[dt.getMonth()]++})}else{d.appts.forEach(x=>{const dt=new Date(x.date+'T12:00:00');values[dt.getMonth()]++})}const max=Math.max(1,...values);return months.map((m,i)=>({m,v:values[i],h:Math.round((values[i]/max)*100)}))}
function renderDashboard(c){const global=['gerencia','sistemas'].includes(state.role),doctors=demo.staff.filter(s=>s.role==='Médico'&&s.workStatus==='Activo'&&(state.dashboardBranch==='Todas las sedes'||s.branch===state.dashboardBranch));const metrics=dashboardMetrics(),series=dashboardSeries();c.innerHTML=`<div class="toolbar"><div class="left"><select id="dashPeriod"><option value="current_month" ${state.dashboardPeriod==='current_month'?'selected':''}>Octubre 2026</option><option value="prev_month" ${state.dashboardPeriod==='prev_month'?'selected':''}>Septiembre 2026</option><option value="year_2026" ${state.dashboardPeriod==='year_2026'?'selected':''}>Año 2026</option><option value="year_2025" ${state.dashboardPeriod==='year_2025'?'selected':''}>Año 2025</option><option value="all" ${state.dashboardPeriod==='all'?'selected':''}>Todo el histórico</option></select><select id="dashBranch" ${global?'':'disabled'}>${branchOptions(true)}</select>${['gerencia','recepcion','medico'].includes(state.role)?`<select id="dashDoctor" ${state.role==='medico'?'disabled':''}><option>Todos los médicos</option>${doctors.map(d=>`<option value="${d.code}">${d.name}</option>`).join('')}</select>`:''}</div><div class="right"><button class="btn btn-outline btn-sm" data-action="export-dashboard">Exportar resumen CSV</button></div></div><div class="kpis">${metrics.map(x=>`<div class="kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="dashgrid"><div class="panel"><h3>${state.role==='caja'||state.role==='gerencia'?'Actividad económica':'Actividad operativa'} por mes</h3><div class="bars">${series.map(x=>`<div class="barcol" title="${x.v}"><div class="bar" style="height:${x.h}%"></div><small>${x.m}</small></div>`).join('')}</div></div><div class="panel"><h3>Resumen para ${roles[state.role]}</h3><p class="muted">Los indicadores se recalculan con el periodo, sede y médico seleccionados.</p><div class="careCard"><b>Ámbito</b><p class="muted">${dashboardData().branch}</p></div><div class="careCard"><b>Datos ficticios cargados</b><p class="muted">20,000 pacientes · 8,000 citas · ${demo.histories.length.toLocaleString('es-PE')} historias · 6,000 comprobantes.</p></div></div></div>`;$('#dashBranch').value=global?state.dashboardBranch:userBranch();if($('#dashDoctor'))$('#dashDoctor').value=state.role==='medico'?state.user.staffCode:state.dashboardDoctor;$('#dashPeriod').onchange=e=>{state.dashboardPeriod=e.target.value;renderDashboard(c)};$('#dashBranch').onchange=e=>{state.dashboardBranch=e.target.value;state.dashboardDoctor='Todos los médicos';renderDashboard(c)};if($('#dashDoctor'))$('#dashDoctor').onchange=e=>{state.dashboardDoctor=e.target.value;renderDashboard(c)}}
function filterControlsBranch(selected,global=true){return `<select class="filter-branch" ${global?'':'disabled'}>${branchOptions(true)}</select>`}
function renderPatients(c){const global=['gerencia','sistemas'].includes(state.role),defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><input id="patientSearch" placeholder="Buscar por DNI, código o nombre"><select id="patientBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="patientStatus"><option>Todos los estados</option><option>Activo</option><option>Pendiente</option></select></div><div class="right">${actionAllowed('new-patient')?'<button class="btn btn-primary" data-action="new-patient">+ Registrar paciente</button>':''}</div></div><div class="notice" style="margin-bottom:12px"><b>Paciente ≠ cuenta del portal.</b> Un paciente puede existir en la clínica y todavía no tener acceso web. El portal se activa cuando crea su cuenta o cuando Recepción genera/invita su acceso.</div><div id="patientsTable"></div>`;$('#patientBranch').value=defaultBranch;const update=()=>{const q=$('#patientSearch').value.toLowerCase(),b=$('#patientBranch').value,st=$('#patientStatus').value;let rows=demo.patients.filter(p=>(b==='Todas las sedes'||p.branch===b)&&(st==='Todos los estados'||p.status===st)&&(`${p.code} ${p.dni} ${p.name}`.toLowerCase().includes(q)));state.pageState.patients=state.pageState.patients||1;$('#patientsTable').innerHTML=pagedTable(['Código','DNI','Paciente','Teléfono','Correo','Sede','Seguro','Estado','Portal'],rows.map(p=>[p.code,p.dni,p.name,p.phone,p.email,p.branch,p.insurance,`<span class="badge ${p.status==='Activo'?'ok':'warn'}">${p.status}</span>`,`<span class="badge ${['Activo','Demo'].includes(p.portalStatus)?'ok':'warn'}">${p.portalStatus||'Sin cuenta'}</span>`]),'patients',25)};['input','change'].forEach(ev=>$('#patientSearch').addEventListener(ev,update));$('#patientBranch').onchange=()=>{state.pageState.patients=1;update()};$('#patientStatus').onchange=()=>{state.pageState.patients=1;update()};update()}
function renderStaff(c){const global=['gerencia','sistemas'].includes(state.role),defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><input id="staffSearch" placeholder="Buscar por nombre, código o correo"><select id="staffBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="staffRole"><option>Todos los cargos</option><option>Médico</option><option>Enfermería</option><option>Recepción</option><option>Caja</option><option>Almacén</option><option>Sistemas</option><option>Gerencia</option></select><select id="staffStatus"><option>Todos los estados</option><option>Activo</option><option>Vacaciones</option><option>Licencia</option><option>Inactivo</option><option>Baja</option></select></div>${actionAllowed('new-staff')?'<button class="btn btn-primary" data-action="new-staff">+ Registrar personal</button>':''}</div><div id="staffSummary"></div><div id="coverageAlert"></div><div id="staffTable"></div>`;$('#staffBranch').value=defaultBranch;const update=()=>{const q=$('#staffSearch').value.toLowerCase(),b=$('#staffBranch').value,r=$('#staffRole').value,st=$('#staffStatus').value;let rows=demo.staff.filter(s=>(b==='Todas las sedes'||s.branch===b)&&(r==='Todos los cargos'||s.role===r)&&(st==='Todos los estados'||s.workStatus===st)&&(`${s.code} ${s.name} ${s.email||''}`.toLowerCase().includes(q)));const counts={Activo:0,Vacaciones:0,Licencia:0,Inactivo:0,Baja:0};rows.forEach(x=>counts[x.workStatus]=(counts[x.workStatus]||0)+1);$('#staffSummary').innerHTML=`<div class="staff-summary"><div class="kpi"><span>Activos</span><strong>${counts.Activo}</strong></div><div class="kpi"><span>Vacaciones</span><strong>${counts.Vacaciones}</strong></div><div class="kpi"><span>Licencia</span><strong>${counts.Licencia}</strong></div><div class="kpi"><span>Inactivos</span><strong>${counts.Inactivo}</strong></div><div class="kpi"><span>Baja</span><strong>${counts.Baja}</strong></div></div>`;const branchScope=b==='Todas las sedes'?branches.map(x=>x.name):[b],gaps=[];for(const br of branchScope){for(const sp of specialties){const docs=demo.staff.filter(x=>x.role==='Médico'&&x.branch===br&&x.specialty===sp);if(docs.length&&!docs.some(x=>x.workStatus==='Activo'))gaps.push(`${br} · ${sp}`)}}$('#coverageAlert').innerHTML=gaps.length?`<div class="coverage-alert"><b>⚠ Cobertura médica por revisar</b><div>Hay especialidades sin médico activo según los estados laborales de la demo.</div><div class="coverage-list">${gaps.slice(0,8).map(x=>`<span class="coverage-pill">${x}</span>`).join('')}</div></div>`:'';$('#staffTable').innerHTML=pagedTable(['Código','Nombre','Rol','Especialidad / función','Sede','Estado laboral','Horario','Vigencia','Correo'],rows.map(s=>[s.code,s.name,s.role,s.specialty,s.branch,workStatusBadge(s.workStatus),staffSchedule(s),`<span class="status-period">${workPeriod(s)}</span>`,s.email||'—']),'staff',25)};['staffSearch','staffBranch','staffRole','staffStatus'].forEach(id=>{const el=$('#'+id);el[id==='staffSearch'?'oninput':'onchange']=()=>{state.pageState.staff=1;update()}});update()}
function renderAppointments(c){const global=state.role==='gerencia',defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><select id="apptBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="apptDoctor"><option>Todos los médicos</option>${demo.staff.filter(s=>s.role==='Médico'&&s.workStatus==='Activo').map(s=>`<option value="${s.code}">${s.name}</option>`).join('')}</select><select id="apptStatus"><option>Todos los estados</option><option>Programada</option><option>Confirmada</option><option>Realizada</option><option>Cancelada</option></select></div>${actionAllowed('new-appointment')?'<button class="btn btn-primary" data-action="new-appointment">+ Nueva cita</button>':''}</div><div id="apptTable"></div>`;$('#apptBranch').value=defaultBranch;if(state.role==='medico'){$('#apptDoctor').value=state.user.staffCode;$('#apptDoctor').disabled=true}const update=()=>{const b=$('#apptBranch').value,d=$('#apptDoctor').value,s=$('#apptStatus').value;let rows=demo.appointments.filter(a=>(b==='Todas las sedes'||a.branch===b)&&(d==='Todos los médicos'||a.doctorCode===d)&&(s==='Todos los estados'||a.status===s));if(state.role==='medico')rows=rows.filter(a=>a.doctorCode===state.user.staffCode);$('#apptTable').innerHTML=pagedTable(['Código','Paciente','Médico','Sede','Fecha','Hora','Estado'],rows.map(a=>[a.id,a.patient,a.doctor,a.branch,a.date,a.time,`<span class="badge ${a.status==='Realizada'?'ok':a.status==='Cancelada'?'danger':'warn'}">${a.status}</span>`]),'appts',25)};$('#apptBranch').onchange=()=>{state.pageState.appts=1;update()};$('#apptDoctor').onchange=()=>{state.pageState.appts=1;update()};$('#apptStatus').onchange=()=>{state.pageState.appts=1;update()};update()}
function renderHistory(c){const global=state.role==='gerencia',defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><input id="historySearch" placeholder="Paciente, código o diagnóstico"><select id="historyBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="historyDoctor"><option>Todos los médicos</option>${demo.staff.filter(s=>s.role==='Médico'&&s.workStatus==='Activo').map(s=>`<option value="${s.code}">${s.name}</option>`).join('')}</select></div></div><div class="notice" style="margin-bottom:14px">Acceso clínico auditado. En una implementación real se aplica mínimo privilegio y registro de accesos.</div><div id="historyTable"></div>`;$('#historyBranch').value=defaultBranch;if(state.role==='medico'){$('#historyDoctor').value=state.user.staffCode;$('#historyDoctor').disabled=true}const update=()=>{const q=$('#historySearch').value.toLowerCase(),b=$('#historyBranch').value,d=$('#historyDoctor').value;let rows=demo.histories.filter(h=>(b==='Todas las sedes'||h.branch===b)&&(d==='Todos los médicos'||h.doctorCode===d)&&(`${h.code} ${h.patient} ${h.diagnosis}`.toLowerCase().includes(q)));if(state.role==='medico')rows=rows.filter(h=>h.doctorCode===state.user.staffCode);$('#historyTable').innerHTML=pagedTable(['Historia','Fecha','Paciente','Médico','Sede','Diagnóstico'],rows.map(h=>[h.code,h.date,h.patient,h.doctor,h.branch,h.diagnosis]),'history',25)};$('#historySearch').oninput=()=>{state.pageState.history=1;update()};$('#historyBranch').onchange=()=>{state.pageState.history=1;update()};$('#historyDoctor').onchange=()=>{state.pageState.history=1;update()};update()}

function norm(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function patientMatches(q,branch='Todas las sedes',limit=8){const raw=String(q||'').trim(),digits=raw.replace(/\D/g,'');if(raw.length<2)return[];return demo.patients.filter(p=>(branch==='Todas las sedes'||p.branch===branch)&&((digits.length>=2&&p.dni.includes(digits))||norm(`${p.code} ${p.name}`).includes(norm(raw)))).slice(0,limit)}
function getPatient(code){return demo.patients.find(p=>p.code===code)}
function invoicePatient(inv){return getPatient(inv.patientCode)||{code:inv.patientCode||'—',dni:'—',name:inv.patient||'—',insurance:'—',branch:inv.branch||'—'}}
function invoiceLines(inv){if(Array.isArray(inv.items)&&inv.items.length)return inv.items;return[{kind:'SERV',code:'SERV-DEMO',description:'Servicios clínicos',qty:1,unitPrice:+inv.total,total:+inv.total}]}
function showInvoiceReceipt(invOrCode){const inv=typeof invOrCode==='string'?demo.invoices.find(x=>x.code===invOrCode):invOrCode;if(!inv){showToast('No se encontró el comprobante');return}const p=invoicePatient(inv),lines=invoiceLines(inv);modal(`<span class="eyebrow">Facturación Nova Salud</span><h2>Comprobante ${inv.code}</h2><div class="receipt"><div class="receipt-head"><div><b>Clínica Nova Salud</b><div class="muted">Sede ${inv.branch}</div></div><div style="text-align:right"><b>${inv.status}</b><div class="muted">${inv.date} · ${inv.time||'—'}</div></div></div><div class="receipt-grid"><div><small class="muted">Paciente</small><br><b>${p.name}</b></div><div><small class="muted">DNI</small><br><b>${p.dni}</b></div><div><small class="muted">Código</small><br>${p.code}</div><div><small class="muted">Seguro</small><br>${p.insurance||'Particular'}</div><div><small class="muted">Método de pago</small><br>${inv.method}</div><div><small class="muted">Sede</small><br>${inv.branch}</div></div>${rowTable(['Concepto','Cant.','P. unitario','Importe'],lines.map(x=>[x.description,x.qty,money(x.unitPrice),money(x.total)]))}<div class="invoice-total"><span>Total</span><strong>${money(inv.total)}</strong></div></div><div class="receipt-actions"><button class="btn btn-outline" data-print-invoice-code="${inv.code}">🖨 Imprimir / Guardar PDF</button><button class="btn btn-primary" data-action="new-invoice">+ Nueva factura</button></div>`)}
function printInvoice(code){const inv=demo.invoices.find(x=>x.code===code);if(!inv)return;const p=invoicePatient(inv),lines=invoiceLines(inv),w=window.open('','_blank','width=850,height=900');if(!w){showToast('El navegador bloqueó la ventana de impresión');return}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${inv.code}</title><style>body{font-family:Arial,sans-serif;color:#17324a;padding:34px}h1{font-size:24px;margin:0}small{color:#657985}.head{display:flex;justify-content:space-between;border-bottom:2px solid #2f7fa7;padding-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 25px;margin:20px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:10px;border-bottom:1px solid #dce9ef;text-align:left}th{background:#eef7fb}.total{text-align:right;font-size:22px;font-weight:bold;margin-top:20px}.foot{margin-top:28px;font-size:12px;color:#667c8b}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>Clínica Nova Salud</h1><small>Sede ${inv.branch}</small></div><div style="text-align:right"><b>${inv.code}</b><br><small>${inv.date} · ${inv.time||'—'}</small></div></div><div class="grid"><div><small>Paciente</small><br><b>${p.name}</b></div><div><small>DNI</small><br><b>${p.dni}</b></div><div><small>Código paciente</small><br>${p.code}</div><div><small>Método</small><br>${inv.method}</div></div><table><thead><tr><th>Concepto</th><th>Cant.</th><th>P. unitario</th><th>Importe</th></tr></thead><tbody>${lines.map(x=>`<tr><td>${x.description}</td><td>${x.qty}</td><td>${money(x.unitPrice)}</td><td>${money(x.total)}</td></tr>`).join('')}</tbody></table><div class="total">TOTAL: ${money(inv.total)}</div><div class="foot">Prototipo académico · comprobante ficticio. En el diálogo de impresión selecciona “Guardar como PDF” para obtener un PDF.</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script>

</body></html>`);w.document.close()}
function renderBilling(c){const global=state.role==='gerencia',defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><input id="billSearch" placeholder="DNI, paciente o comprobante"><select id="billBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="billMethod"><option>Todos los métodos</option><option>Yape</option><option>Efectivo</option><option>Tarjeta de débito</option><option>Tarjeta de crédito</option><option>Depósito</option></select></div>${actionAllowed('new-invoice')?'<button class="btn btn-primary" data-action="new-invoice">+ Nueva factura</button>':''}</div><div id="billingTable"></div>`;$('#billBranch').value=defaultBranch;const update=()=>{const q=norm($('#billSearch').value),digits=$('#billSearch').value.replace(/\D/g,''),b=$('#billBranch').value,m=$('#billMethod').value;const rows=demo.invoices.filter(x=>{const p=invoicePatient(x),hay=`${x.code} ${p.code} ${p.dni} ${p.name}`;return(b==='Todas las sedes'||x.branch===b)&&(m==='Todos los métodos'||x.method===m)&&(!q||norm(hay).includes(q)||(digits&&String(p.dni).includes(digits)))}).sort((a,b)=>`${b.date} ${b.time||''}`.localeCompare(`${a.date} ${a.time||''}`));$('#billingTable').innerHTML=pagedTable(['Comprobante','Fecha / hora','DNI','Paciente','Sede','Total','Método','Estado','Acción'],rows.map(x=>{const p=invoicePatient(x);return[x.code,`${x.date}<br><small>${x.time||'—'}</small>`,p.dni,p.name,x.branch,money(x.total),x.method,`<span class="badge ${x.status==='Pagado'?'ok':'warn'}">${x.status}</span>`,`<button class="btn btn-outline btn-sm" data-invoice-code="${x.code}">Ver / imprimir</button>`]}),'billing',25)};$('#billSearch').oninput=()=>{state.pageState.billing=1;update()};$('#billBranch').onchange=()=>{state.pageState.billing=1;update()};$('#billMethod').onchange=()=>{state.pageState.billing=1;update()};update()}
function renderInventory(c){const global=state.role==='gerencia',defaultBranch=global?'Todas las sedes':userBranch();c.innerHTML=`<div class="toolbar"><div class="left"><input id="invSearch" placeholder="Buscar producto"><select id="invBranch" ${global?'':'disabled'}>${branchOptions(true)}</select><select id="invWarehouse"><option>Todos los almacenes</option>${warehouses.map(w=>`<option>${w.name}</option>`).join('')}</select></div><div class="right">${actionAllowed('movement')?'<button class="btn btn-outline" data-action="movement">Registrar movimiento</button>':''}${actionAllowed('new-product')?'<button class="btn btn-primary" data-action="new-product">+ Nuevo producto</button>':''}</div></div><div id="inventoryTable"></div>`;$('#invBranch').value=defaultBranch;const update=()=>{const q=$('#invSearch').value.toLowerCase(),b=$('#invBranch').value,w=$('#invWarehouse').value;let rows=demo.stock.filter(p=>(b==='Todas las sedes'||p.branch===b)&&(w==='Todos los almacenes'||p.warehouse===w)&&p.product.toLowerCase().includes(q));if(!global)rows=rows.filter(p=>p.branch===userBranch());$('#inventoryTable').innerHTML=rowTable(['Producto','Almacén','Sede','Lote','Vence','Stock','Mínimo','Precio','Estado'],rows.map(p=>[p.product,p.warehouse,p.branch,p.batch,p.expiry,p.qty,p.min,money(p.price),p.qty<=p.min?'<span class="badge danger">Crítico</span>':'<span class="badge ok">Disponible</span>']))};$('#invSearch').oninput=update;$('#invBranch').onchange=update;$('#invWarehouse').onchange=update;update()}
function renderBranches(c){c.innerHTML=`<div class="toolbar"><div class="left"><input id="branchSearch" placeholder="Buscar sede"></div></div><div id="branchGrid" class="grid3"></div>`;const update=()=>{const q=norm($('#branchSearch').value),rows=branches.filter(b=>!q||norm(`${b.code} ${b.name} ${b.address}`).includes(q));$('#branchGrid').innerHTML=rows.map(b=>{const pat=demo.patients.filter(p=>p.branch===b.name).length,docs=demo.staff.filter(x=>x.branch===b.name&&x.role==='Médico').length,staff=demo.staff.filter(x=>x.branch===b.name).length,wh=warehouses.find(w=>w.branch===b.name);return`<div class="card"><span class="badge">${b.code}</span><h3>Nova Salud ${b.name}</h3><p>${b.address}</p><p>${b.phone}</p><div class="branch-metrics"><div class="branch-metric"><small>Pacientes</small><b>${pat.toLocaleString('es-PE')}</b></div><div class="branch-metric"><small>Médicos</small><b>${docs}</b></div><div class="branch-metric"><small>Personal</small><b>${staff}</b></div></div><p><b>Almacén:</b> ${wh.code}</p><div class="card-actions"><button class="btn btn-outline btn-sm" data-branch-detail="${b.name}">Ver detalle</button></div></div>`}).join('')};$('#branchSearch').oninput=update;update()}

function showBranchDetail(name){const b=branches.find(x=>x.name===name);if(!b)return;const wh=warehouses.find(w=>w.branch===name),patients=demo.patients.filter(p=>p.branch===name),staff=demo.staff.filter(x=>x.branch===name),appts=demo.appointments.filter(a=>a.branch===name),invoices=demo.invoices.filter(i=>i.branch===name),stock=demo.stock.filter(x=>x.branch===name),low=stock.filter(x=>x.qty<=x.min).length,revenue=invoices.filter(i=>i.status==='Pagado').reduce((a,x)=>a+(+x.total||0),0);modal(`<span class="eyebrow">Sede Nova Salud</span><h2>${b.name}</h2><p class="muted">${b.address} · ${b.phone}</p><p><b>Consulta externa:</b> ${b.consultHours} · <b>Farmacia:</b> ${b.pharmacyHours} · <b>Emergencia:</b> ${b.emergencyHours}</p><div class="branch-metrics"><div class="branch-metric"><small>Pacientes</small><b>${patients.length.toLocaleString('es-PE')}</b></div><div class="branch-metric"><small>Personal</small><b>${staff.length}</b></div><div class="branch-metric"><small>Médicos</small><b>${staff.filter(x=>x.role==='Médico').length}</b></div><div class="branch-metric"><small>Citas históricas</small><b>${appts.length.toLocaleString('es-PE')}</b></div><div class="branch-metric"><small>Facturación demo</small><b>${money(revenue)}</b></div><div class="branch-metric"><small>Stock crítico</small><b>${low}</b></div></div><div class="notice"><b>Almacén:</b> ${wh.name} (${wh.code}). Los indicadores se calculan desde los registros ficticios de esta sede.</div>`,true)}
function renderAudit(c){c.innerHTML=`<div class="toolbar"><div class="left"><input id="auditSearch" placeholder="Buscar usuario, entidad o registro"><select id="auditAction"><option>Todas las acciones</option><option>INSERT</option><option>UPDATE</option><option>DELETE</option><option>LOGIN</option></select></div></div><div id="auditTable"></div>`;const update=()=>{const q=$('#auditSearch').value.toLowerCase(),a=$('#auditAction').value;const rows=demo.audit.filter(x=>(a==='Todas las acciones'||x.action===a)&&(`${x.user} ${x.entity} ${x.record} ${x.detail}`.toLowerCase().includes(q)));$('#auditTable').innerHTML=pagedTable(['Fecha','Usuario','Acción','Entidad','Registro','Detalle'],rows.map(x=>[x.date,x.user,x.action,x.entity,x.record,x.detail]),'audit',25)};$('#auditSearch').oninput=update;$('#auditAction').onchange=update;update()}
function renderSupport(c){c.innerHTML=`<div class="toolbar"><div><h3 style="margin:0">Soporte</h3><p class="muted">Incidencias internas del sistema.</p></div>${actionAllowed('new-ticket')?'<button class="btn btn-primary" data-action="new-ticket">+ Nuevo ticket</button>':''}</div>${rowTable(['Ticket','Fecha','Prioridad','Estado','Sede','Descripción'],demo.support.map(s=>[s.code,s.date,s.priority,s.status,s.branch,s.description]))}`}
function go(page){if(state.role==='patient'){state.page=page;renderPatientSide();const p=state.user.patient;if(page==='patient-home')return renderPatientHome();if(page==='patient-appointments'){const rows=demo.appointments.filter(a=>a.patientCode===p.code);$('#pageTitle').textContent='Mis citas';$('#appContent').innerHTML=`<div class="toolbar"><div><h3 style="margin:0">Mis citas</h3></div><button class="btn btn-primary" data-action="patient-book">+ Solicitar cita</button></div>${rowTable(['Código','Fecha','Hora','Médico','Sede','Estado'],rows.map(a=>[a.id,a.date,a.time,a.doctor,a.branch,a.status]))}`;return}if(page==='patient-profile'){$('#pageTitle').textContent='Mi perfil';$('#appContent').innerHTML=`<div class="panel"><h3>Datos personales</h3><div class="formgrid"><label>Código<input value="${p.code}" disabled></label><label>DNI<input value="${p.dni}"></label><label>Nombre<input value="${p.name}"></label><label>Teléfono<input value="${p.phone}"></label><label>Correo<input value="${p.email}"></label><label>Sede<input value="${p.branch}" disabled></label></div><button class="btn btn-primary" style="margin-top:15px" data-action="fake-save">Guardar cambios</button></div>`;return}if(page==='patient-payments'){const rows=demo.invoices.filter(i=>i.patientCode===p.code);$('#pageTitle').textContent='Mis pagos';$('#appContent').innerHTML=rowTable(['Comprobante','Fecha / hora','Monto','Método','Estado'],rows.map(i=>[i.code,`${i.date} ${i.time||''}`,money(i.total),i.method,i.status]));return}return}
 if(!can(page)){showToast('Acceso denegado para este rol');page='dashboard'}state.page=page;renderNav();const titles={dashboard:'Dashboard',patients:'Pacientes',staff:'Personal',appointments:'Citas',history:'Historial clínico',billing:'Facturación y caja',inventory:'Inventario',branches:'Sedes',audit:'Auditoría',support:'Soporte'};$('#pageTitle').textContent=titles[page]||page;$('#pageKicker').textContent=`${roles[state.role]} · Clínica Nova Salud`;const c=$('#appContent');if(page==='dashboard')renderDashboard(c);if(page==='patients')renderPatients(c);if(page==='staff')renderStaff(c);if(page==='appointments')renderAppointments(c);if(page==='history')renderHistory(c);if(page==='billing')renderBilling(c);if(page==='inventory')renderInventory(c);if(page==='branches')renderBranches(c);if(page==='audit')renderAudit(c);if(page==='support')renderSupport(c)}
function simpleForm(title,fields,onSubmit){modal(`<span class="eyebrow">Nova Salud</span><h2>${title}</h2><form id="simpleForm"><div class="formgrid">${fields.map(f=>`<label>${f.label}${f.type==='select'?`<select name="${f.name}">${f.options}</select>`:f.type==='textarea'?`<textarea name="${f.name}" ${f.required===false?'':'required'}></textarea>`:`<input name="${f.name}" type="${f.type||'text'}" ${f.required===false?'':'required'} ${f.placeholder?`placeholder="${f.placeholder}"`:''} ${f.min!=null?`min="${f.min}"`:''}>`}</label>`).join('')}</div><button class="btn btn-primary" style="margin-top:16px">Guardar</button></form>`);$('#simpleForm').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.target))}}
function openNewPatient(){simpleForm('Registrar paciente',[{label:'DNI',name:'dni'},{label:'Nombres',name:'first'},{label:'Apellidos',name:'last'},{label:'Teléfono',name:'phone'},{label:'Correo',name:'email',type:'email'},{label:'Sede',name:'branch',type:'select',options:branchOptions()},{label:'Seguro',name:'insurance',type:'select',options:'<option>Particular</option><option>SIS</option><option>Rímac</option><option>Pacífico</option><option>Mapfre</option>'}],fd=>{if(demo.patients.some(p=>p.dni===fd.get('dni'))){showToast('Ese DNI ya está registrado');return}const code=nextCode('PAC',demo.patients,'code',20001);demo.patients.push({code,dni:fd.get('dni'),name:`${fd.get('first')} ${fd.get('last')}`,phone:fd.get('phone'),email:fd.get('email'),branch:fd.get('branch'),insurance:fd.get('insurance'),status:'Activo',portalStatus:'Sin cuenta',registered:isoDate(DEMO_TODAY)});addAudit('INSERT','paciente',code,'Paciente registrado por personal; portal aún no activado');closeModal();showToast('Paciente registrado · portal sin activar');go('patients')})}
