function runSelfTest(){const results=[],assert=(name,ok,detail='')=>results.push({name,ok,detail});const caja=demo.accounts.find(a=>a.role==='caja'&&a.branch==='Chorrillos');state.role=caja.role;state.user=caja;assert('Caja no puede ver Inventario',!can('inventory'));assert('Caja sí puede ver Facturación',can('billing'));assert('Hay 5 almacenes',warehouses.length===5,String(warehouses.length));assert('Hay 25 médicos',demo.staff.filter(s=>s.role==='Médico').length===25);assert('Hay 50 enfermería',demo.staff.filter(s=>s.role==='Enfermería').length===50);assert('Hay al menos 500 historias',demo.histories.length>=500,String(demo.histories.length));const mgr=demo.accounts.find(a=>a.role==='gerencia');state.role='gerencia';state.user=mgr;state.dashboardPeriod='year_2026';state.dashboardBranch='Todas las sedes';const all=dashboardData().appts.length;state.dashboardBranch='Miraflores';const mir=dashboardData().appts.length;assert('Dashboard cambia por sede',mir<all,`${mir} < ${all}`);const mirStaff=demo.staff.filter(s=>s.branch==='Miraflores');assert('Filtro de personal por sede devuelve 18',mirStaff.length===18,String(mirStaff.length));assert('Miraflores tiene 5 médicos',mirStaff.filter(s=>s.role==='Médico').length===5);const before=demo.products.length;demo.products.push({code:'PRD-SELFTEST',name:'Producto test',category:'Test',min:1,price:1});assert('Registro de producto modifica catálogo',demo.products.length===before+1);demo.products.pop();assert('Políticas presentes',!!document.querySelector('[data-action="privacy"]')&&!!document.querySelector('[data-action="arco"]'));assert('Buscador de paciente por DNI funciona',patientMatches('50000101','Chorrillos').length===1);assert('Facturación tiene función de comprobante',typeof showInvoiceReceipt==='function'&&typeof printInvoice==='function');assert('Nombres de pacientes tienen baja repetición',new Set(demo.patients.slice(0,5000).map(p=>p.name)).size>4900,String(new Set(demo.patients.slice(0,5000).map(p=>p.name)).size));assert('Existen pacientes con compras repetidas',new Set(demo.invoices.map(i=>i.patientCode)).size<demo.invoices.length);assert('Totales de facturación son variados',new Set(demo.invoices.slice(0,1000).map(i=>i.total)).size>50,String(new Set(demo.invoices.slice(0,1000).map(i=>i.total)).size));assert('Facturas incluyen horas variadas',new Set(demo.invoices.slice(0,500).map(i=>i.time)).size>20,String(new Set(demo.invoices.slice(0,500).map(i=>i.time)).size));assert('Catálogo incluye movilidad clínica',demo.products.some(p=>p.name.includes('Silla de ruedas'))&&demo.products.some(p=>p.name.includes('Muletas')));assert('Personal tiene estados laborales',new Set(demo.staff.map(s=>s.workStatus)).size>=4,[...new Set(demo.staff.map(s=>s.workStatus))].join(','));assert('Especialistas públicos excluyen no activos',demo.staff.filter(s=>s.role==='Médico'&&s.workStatus!=='Activo').length>0);assert('Horarios públicos presentes',!!document.querySelector('#horarios')&&!!document.querySelector('#emergencias'));document.body.innerHTML=`<pre id="selftest">${results.map(r=>`${r.ok?'PASS':'FAIL'} | ${r.name}${r.detail?' | '+r.detail:''}`).join('\n')}</pre>`}
if(location.search.includes('selftest=1'))setTimeout(runSelfTest,50);
;

