// Dashboard v5.6: analítica, inventario, personal y datos ficticios realistas. Usa datos ficticios locales de la demo.
state.dashboardTab = state.dashboardTab || null;
const DASH_COLORS=['#2f7fa7','#5aa8c7','#7cc4d9','#95b8c9','#b8d6e2','#4f8da8'];
function dashAllowedTabs(){
 const map={gerencia:['executive','clinical','finance','inventory'],caja:['finance'],almacen:['inventory'],recepcion:['clinical'],medico:['clinical'],enfermeria:['clinical'],sistemas:['executive']};
 return map[state.role]||['executive'];
}
function dashTabName(k){return {executive:'Resumen ejecutivo',clinical:'Atención médica',finance:'Finanzas',inventory:'Inventario y sedes'}[k]||k}
function dashPeriodLabel(){return {current_month:'Octubre 2026',prev_month:'Septiembre 2026',year_2026:'Año 2026',year_2025:'Año 2025',all:'Histórico completo'}[state.dashboardPeriod]||state.dashboardPeriod}
function dashBranch(){return ['gerencia','sistemas'].includes(state.role)?state.dashboardBranch:userBranch()}
function dashFilter(rows,dateField='date',doctor=false){
 const branch=dashBranch();
 return rows.filter(x=>periodMatch(x[dateField],state.dashboardPeriod))
   .filter(x=>branch==='Todas las sedes'||x.branch===branch)
   .filter(x=>!doctor||state.dashboardDoctor==='Todos los médicos'||x.doctorCode===state.dashboardDoctor)
   .filter(x=>!doctor||state.role!=='medico'||x.doctorCode===state.user.staffCode);
}
function dashAppointmentRows(){return dashFilter(demo.appointments,'date',true)}
function dashInvoiceRows(){return dashFilter(demo.invoices,'date',false)}
function dashPatientRows(){return dashFilter(demo.patients,'registered',false)}
function dashMovementRows(){return dashFilter(demo.movements,'date',false)}
function dashHistoryRows(){return dashFilter(demo.histories,'date',true)}
function groupCount(rows,keyFn){const m={};rows.forEach(x=>{const k=keyFn(x)||'Sin dato';m[k]=(m[k]||0)+1});return m}
function groupSum(rows,keyFn,valFn){const m={};rows.forEach(x=>{const k=keyFn(x)||'Sin dato';m[k]=(m[k]||0)+Number(valFn(x)||0)});return m}
function entriesSorted(obj,desc=true){return Object.entries(obj).sort((a,b)=>desc?b[1]-a[1]:a[1]-b[1])}
function trendBuckets(rows,valueFn,dateField='date'){
 const monthMode=['current_month','prev_month'].includes(state.dashboardPeriod);
 if(monthMode){
   const labels=['1–5','6–10','11–15','16–20','21–25','26–31'],values=Array(6).fill(0);
   rows.forEach(x=>{const d=new Date(x[dateField]+'T12:00:00');const i=Math.min(5,Math.floor((d.getDate()-1)/5));values[i]+=Number(valueFn(x)||0)});
   return labels.map((label,i)=>({label,value:values[i]}));
 }
 const labels=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'],values=Array(12).fill(0);
 rows.forEach(x=>{const d=new Date(x[dateField]+'T12:00:00');values[d.getMonth()]+=Number(valueFn(x)||0)});
 return labels.map((label,i)=>({label,value:values[i]}));
}
function lineChart(data,{currency=false}={}){
 const W=720,H=260,L=44,R=18,T=22,B=36,max=Math.max(1,...data.map(x=>x.value));
 const pts=data.map((x,i)=>{const px=L+(data.length===1?0:(i*(W-L-R)/(data.length-1))),py=T+(H-T-B)*(1-x.value/max);return {...x,x:px,y:py}});
 const poly=pts.map(p=>`${p.x},${p.y}`).join(' '),area=`${L},${H-B} ${poly} ${pts.length?pts[pts.length-1].x:L},${H-B}`;
 const grid=[0,.25,.5,.75,1].map(q=>{const y=T+(H-T-B)*(1-q);return `<line class="chart-axis" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/>`}).join('');
 return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${grid}<polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${poly}"/>${pts.map((p,i)=>`<circle class="chart-dot" cx="${p.x}" cy="${p.y}" r="4"/><text class="chart-label" x="${p.x}" y="${H-12}" text-anchor="middle">${p.label}</text>${(data.length<=6||i%2===0)?`<text class="chart-value" x="${p.x}" y="${Math.max(12,p.y-9)}" text-anchor="middle">${currency?'S/'+Math.round(p.value).toLocaleString('es-PE'):Math.round(p.value).toLocaleString('es-PE')}</text>`:''}`).join('')}</svg>`;
}
function donutChart(items,centerLabel='Total'){
 const clean=items.filter(x=>x.value>0),total=clean.reduce((a,x)=>a+x.value,0)||1;let acc=0,stops=[];
 clean.forEach((x,i)=>{const start=acc/total*360;acc+=x.value;const end=acc/total*360;stops.push(`${DASH_COLORS[i%DASH_COLORS.length]} ${start}deg ${end}deg`)});
 const bg=stops.length?`conic-gradient(${stops.join(',')})`:'#edf3f6';
 return `<div class="donut-wrap"><div class="donut" style="background:${bg}"><div class="donut-center"><div>${total.toLocaleString('es-PE')}<small>${centerLabel}</small></div></div></div><div class="legend">${clean.slice(0,6).map((x,i)=>`<div class="legend-row"><span class="legend-dot" style="background:${DASH_COLORS[i%DASH_COLORS.length]}"></span><span>${x.label}</span><strong>${(x.value/total*100).toFixed(1)}%</strong></div>`).join('')||'<div class="muted">Sin datos</div>'}</div></div>`;
}
function hBars(items,{currency=false,limit=8}={}){
 const arr=items.slice(0,limit),max=Math.max(1,...arr.map(x=>x.value));return `<div class="hbars">${arr.map(x=>`<div class="hbar-row"><span>${x.label}</span><div class="hbar-track"><div class="hbar-fill" style="width:${Math.max(2,x.value/max*100)}%"></div></div><strong>${currency?money(x.value):Number(x.value).toLocaleString('es-PE')}</strong></div>`).join('')||'<div class="muted">Sin datos para los filtros.</div>'}</div>`
}
function dashKpis(items){return `<div class="kpis">${items.map(x=>`<div class="kpi"><span class="kpi-icon">${x.icon||'•'}</span><span>${x.label}</span><strong>${x.value}</strong><span class="kpi-sub">${x.sub||dashPeriodLabel()}</span></div>`).join('')}</div>`}
function dashTable(headers,rows){return `<div class="tablewrap"><table class="mini-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Sin resultados.</td></tr>`}</tbody></table></div>`}
function renderDashExecutive(){
 const appts=dashAppointmentRows(),inv=dashInvoiceRows(),pats=dashPatientRows(),paid=inv.filter(x=>x.status==='Pagado'),revenue=paid.reduce((a,x)=>a+x.total,0),critical=scopeBranch(demo.stock,'branch',dashBranch()).filter(x=>x.qty<=x.min).length;
 const pay=entriesSorted(groupCount(paid,x=>x.method)).map(([label,value])=>({label,value}));
 const byBranch=entriesSorted(groupSum(paid,x=>x.branch,x=>x.total)).map(([label,value])=>({label,value}));
 const status=entriesSorted(groupCount(appts,x=>x.status)).map(([label,value])=>({label,value}));
 const staffScope=demo.staff.filter(x=>dashBranch()==='Todas las sedes'||x.branch===dashBranch()||x.branch==='Central'),staffStates=entriesSorted(groupCount(staffScope,x=>x.workStatus||'Activo')).map(([label,value])=>({label,value}));const gaps=[];for(const br of (dashBranch()==='Todas las sedes'?branches.map(x=>x.name):[dashBranch()]))for(const sp of specialties){const docs=demo.staff.filter(x=>x.role==='Médico'&&x.branch===br&&x.specialty===sp);if(docs.length&&!docs.some(x=>x.workStatus==='Activo'))gaps.push([br,sp,docs[0].workStatus])}return `${dashKpis([{label:'Pacientes registrados en el periodo',value:pats.length.toLocaleString('es-PE'),icon:'👥'},{label:'Citas del periodo',value:appts.length.toLocaleString('es-PE'),icon:'📅'},{label:'Facturación pagada',value:money(revenue),icon:'S/'},{label:'Stock crítico',value:critical.toLocaleString('es-PE'),icon:'⚠'}])}<div class="analytics-grid"><div class="chart-card"><h3>Facturación en el tiempo</h3><div class="chart-sub">Evolución para ${dashPeriodLabel()} · ${dashBranch()}</div>${lineChart(trendBuckets(paid,x=>x.total),{currency:true})}</div><div class="chart-card"><h3>Métodos de pago</h3><div class="chart-sub">Distribución de comprobantes pagados</div>${donutChart(pay,'pagos')}</div></div><div class="analytics-grid equal"><div class="chart-card"><h3>Facturación por sede</h3><div class="chart-sub">Comparación de ingresos</div>${hBars(byBranch,{currency:true,limit:5})}</div><div class="chart-card"><h3>Estado de las citas</h3><div class="chart-sub">Composición del periodo seleccionado</div>${donutChart(status,'citas')}</div></div>${state.role==='gerencia'?`<div class="analytics-grid equal"><div class="chart-card"><h3>Estado del personal</h3><div class="chart-sub">Activos, vacaciones, licencias, inactivos y bajas</div>${donutChart(staffStates,'personas')}</div><div class="chart-card"><h3>Cobertura médica</h3><div class="chart-sub">Especialidades temporalmente sin médico activo</div>${gaps.length?dashTable(['Sede','Especialidad','Situación'],gaps.slice(0,8)):'<div class="notice">Cobertura completa para los filtros actuales.</div>'}</div></div>`:''}`;
}
function renderDashClinical(){
 const appts=dashAppointmentRows(),hist=dashHistoryRows(),done=appts.filter(x=>x.status==='Realizada').length,cancel=appts.filter(x=>x.status==='Cancelada').length;
 const status=entriesSorted(groupCount(appts,x=>x.status)).map(([label,value])=>({label,value}));
 const specialty=entriesSorted(groupCount(appts,x=>demo.staff.find(s=>s.code===x.doctorCode)?.specialty||'Sin especialidad')).map(([label,value])=>({label,value}));
 return `${dashKpis([{label:'Citas',value:appts.length.toLocaleString('es-PE'),icon:'📅'},{label:'Realizadas',value:done.toLocaleString('es-PE'),icon:'✓'},{label:'Canceladas',value:cancel.toLocaleString('es-PE'),icon:'×'},{label:'Historias generadas',value:hist.length.toLocaleString('es-PE'),icon:'📋'}])}<div class="analytics-grid"><div class="chart-card"><h3>Atenciones en el tiempo</h3><div class="chart-sub">Cantidad de citas por periodo</div>${lineChart(trendBuckets(appts,()=>1))}</div><div class="chart-card"><h3>Estado de citas</h3><div class="chart-sub">Programadas, confirmadas, realizadas y canceladas</div>${donutChart(status,'citas')}</div></div><div class="analytics-grid equal"><div class="chart-card"><h3>Especialidades más solicitadas</h3><div class="chart-sub">Según el médico asignado a cada cita</div>${hBars(specialty,{limit:7})}</div><div class="chart-card"><h3>Indicador de cumplimiento</h3><div class="chart-sub">Porcentaje de citas realizadas respecto del total</div>${donutChart([{label:'Realizadas',value:done},{label:'Otras',value:Math.max(0,appts.length-done)}],'citas')}</div></div>`;
}
function renderDashFinance(){
 const inv=dashInvoiceRows(),paid=inv.filter(x=>x.status==='Pagado'),pending=inv.filter(x=>x.status==='Pendiente'),revenue=paid.reduce((a,x)=>a+x.total,0),ticket=paid.length?revenue/paid.length:0;
 const methods=entriesSorted(groupSum(paid,x=>x.method,x=>x.total)).map(([label,value])=>({label,value}));
 const branches=entriesSorted(groupSum(paid,x=>x.branch,x=>x.total)).map(([label,value])=>({label,value}));
 const recent=inv.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(x=>[x.code,x.date,x.patient,x.branch,money(x.total),x.method,x.status]);
 return `${dashKpis([{label:'Ingresos pagados',value:money(revenue),icon:'S/'},{label:'Comprobantes',value:inv.length.toLocaleString('es-PE'),icon:'🧾'},{label:'Pendientes',value:pending.length.toLocaleString('es-PE'),icon:'⏳'},{label:'Ticket promedio',value:money(ticket),icon:'◉'}])}<div class="analytics-grid"><div class="chart-card"><h3>Ventas / facturación por periodo</h3><div class="chart-sub">Solo comprobantes con estado Pagado</div>${lineChart(trendBuckets(paid,x=>x.total),{currency:true})}</div><div class="chart-card"><h3>Ingresos por método de pago</h3><div class="chart-sub">Participación sobre el monto pagado</div>${donutChart(methods,'S/')}</div></div><div class="analytics-grid equal"><div class="chart-card"><h3>Ingresos por sede</h3><div class="chart-sub">Comparación de las cinco sedes</div>${hBars(branches,{currency:true,limit:5})}</div><div class="chart-card"><h3>Últimos comprobantes</h3><div class="chart-sub">Muestra de las operaciones filtradas</div>${dashTable(['Comprobante','Fecha','Paciente','Sede','Total','Método','Estado'],recent)}</div></div>`;
}
function renderDashInventory(){
 const mov=dashMovementRows(),stock=scopeBranch(demo.stock,'branch',dashBranch()),critical=stock.filter(x=>x.qty<=x.min),ware=scopeBranch(warehouses,'branch',dashBranch());
 const types=entriesSorted(groupCount(mov,x=>x.type)).map(([label,value])=>({label,value}));
 const stockBranch=entriesSorted(groupSum(stock,x=>x.branch,x=>x.qty)).map(([label,value])=>({label,value}));
 const crit=critical.slice().sort((a,b)=>(a.qty-a.min)-(b.qty-b.min)).slice(0,10).map(x=>[x.product,x.branch,x.warehouse,x.qty,x.min,x.expiry]);
 return `${dashKpis([{label:'Productos catálogo',value:demo.products.length.toLocaleString('es-PE'),icon:'💊'},{label:'Stock crítico',value:critical.length.toLocaleString('es-PE'),icon:'⚠'},{label:'Movimientos',value:mov.length.toLocaleString('es-PE'),icon:'↕'},{label:'Almacenes',value:ware.length.toLocaleString('es-PE'),icon:'▣'}])}<div class="analytics-grid"><div class="chart-card"><h3>Stock total por sede</h3><div class="chart-sub">Unidades disponibles por ubicación</div>${hBars(stockBranch,{limit:5})}</div><div class="chart-card"><h3>Tipos de movimiento</h3><div class="chart-sub">Entradas, salidas, ventas y uso clínico</div>${donutChart(types,'mov.')}</div></div><div class="chart-card"><h3>Productos en nivel crítico</h3><div class="chart-sub">Prioridad para reposición</div>${dashTable(['Producto','Sede','Almacén','Stock','Mínimo','Vencimiento'],crit)}</div>`;
}
function dashContent(){
 if(state.dashboardTab==='clinical')return renderDashClinical();
 if(state.dashboardTab==='finance')return renderDashFinance();
 if(state.dashboardTab==='inventory')return renderDashInventory();
 return renderDashExecutive();
}
function renderDashboard(c){
 const allowed=dashAllowedTabs();if(!state.dashboardTab||!allowed.includes(state.dashboardTab))state.dashboardTab=allowed[0];
 const global=['gerencia','sistemas'].includes(state.role),doctors=demo.staff.filter(s=>s.role==='Médico'&&s.workStatus==='Activo'&&(state.dashboardBranch==='Todas las sedes'||s.branch===state.dashboardBranch));
 c.innerHTML=`<div class="dashboard-shell"><div class="dash-tabs">${allowed.map(k=>`<button class="dash-tab ${state.dashboardTab===k?'active':''}" data-dash-tab="${k}">${dashTabName(k)}</button>`).join('')}</div><div class="dash-filterbar"><div class="filters"><select id="dashPeriod"><option value="current_month" ${state.dashboardPeriod==='current_month'?'selected':''}>Octubre 2026</option><option value="prev_month" ${state.dashboardPeriod==='prev_month'?'selected':''}>Septiembre 2026</option><option value="year_2026" ${state.dashboardPeriod==='year_2026'?'selected':''}>Año 2026</option><option value="year_2025" ${state.dashboardPeriod==='year_2025'?'selected':''}>Año 2025</option><option value="all" ${state.dashboardPeriod==='all'?'selected':''}>Todo el histórico</option></select><select id="dashBranch" ${global?'':'disabled'}>${branchOptions(true)}</select>${state.dashboardTab==='clinical'&&['gerencia','recepcion','medico','enfermeria'].includes(state.role)?`<select id="dashDoctor" ${state.role==='medico'?'disabled':''}><option>Todos los médicos</option>${doctors.map(d=>`<option value="${d.code}">${d.name}</option>`).join('')}</select>`:''}</div><div class="exports"><button class="btn btn-outline btn-sm" data-action="export-dashboard-excel">Excel / CSV</button><button class="btn btn-outline btn-sm" data-action="print-dashboard">Imprimir / PDF</button></div></div><div class="dashboard-note"><b>Dashboard analítico de demostración:</b> los gráficos se recalculan con los filtros seleccionados. En la etapa PostgreSQL, estos mismos componentes leerán los datos desde la API en lugar del arreglo ficticio local.</div><div class="dashboard-report" id="dashboardReport">${dashContent()}</div></div>`;
 $('#dashBranch').value=global?state.dashboardBranch:userBranch();if($('#dashDoctor'))$('#dashDoctor').value=state.role==='medico'?state.user.staffCode:state.dashboardDoctor;
 $('#dashPeriod').onchange=e=>{state.dashboardPeriod=e.target.value;renderDashboard(c)};
 $('#dashBranch').onchange=e=>{state.dashboardBranch=e.target.value;state.dashboardDoctor='Todos los médicos';renderDashboard(c)};
 if($('#dashDoctor'))$('#dashDoctor').onchange=e=>{state.dashboardDoctor=e.target.value;renderDashboard(c)};
}
function dashboardExportRowsV53(){
 const meta=[['Clínica Nova Salud'],['Dashboard',dashTabName(state.dashboardTab)],['Periodo',dashPeriodLabel()],['Sede',dashBranch()],[]];
 if(state.dashboardTab==='finance'||state.dashboardTab==='executive'){
   const rows=dashInvoiceRows();return [...meta,['Comprobante','Fecha','Paciente','Sede','Total','Método','Estado'],...rows.map(x=>[x.code,x.date,x.patient,x.branch,x.total,x.method,x.status])];
 }
 if(state.dashboardTab==='clinical'){
   const rows=dashAppointmentRows();return [...meta,['Cita','Fecha','Hora','Paciente','Médico','Sede','Estado'],...rows.map(x=>[x.id,x.date,x.time,x.patient,x.doctor,x.branch,x.status])];
 }
 const rows=dashMovementRows();return [...meta,['Movimiento','Fecha','Tipo','Producto','Cantidad','Almacén','Sede'],...rows.map(x=>[x.code,x.date,x.type,x.product,x.qty,x.warehouse,x.branch])];
}
function printDashboardV53(){
 const report=document.getElementById('dashboardReport');if(!report)return;const w=window.open('','_blank','width=1200,height=900');if(!w){showToast('El navegador bloqueó la ventana de impresión');return}
 w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Dashboard Nova Salud</title><style>body{font-family:Arial,sans-serif;color:#17324a;padding:28px}h1{margin:0 0 4px}.meta{color:#667c8b;margin-bottom:20px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.kpi,.chart-card{border:1px solid #dce9ef;border-radius:12px;padding:14px;margin-bottom:12px}.kpi span{display:block;color:#667c8b;font-size:12px}.kpi strong{font-size:20px}.kpi-icon,.kpi-sub{display:none}.analytics-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.chart-svg{width:100%;height:240px}.chart-area{fill:#e7f3f8}.chart-line{fill:none;stroke:#2f7fa7;stroke-width:3}.chart-axis{stroke:#d9e6ec}.chart-dot{fill:#fff;stroke:#2f7fa7;stroke-width:2}.chart-label,.chart-value{font-size:10px;fill:#496575}.donut-wrap{display:flex;gap:18px;align-items:center}.donut{width:140px;height:140px;border-radius:50%;position:relative}.donut:after{content:"";position:absolute;inset:28px;background:white;border-radius:50%}.donut-center{display:none}.legend-row,.hbar-row{display:grid;grid-template-columns:12px 1fr auto;gap:8px;margin:6px 0;font-size:12px}.legend-dot{width:10px;height:10px;border-radius:50%}.hbar-track{height:8px;background:#edf3f6;border-radius:10px}.hbar-fill{height:100%;background:#2f7fa7;border-radius:10px}.mini-table{width:100%;border-collapse:collapse;font-size:11px}.mini-table th,.mini-table td{border-bottom:1px solid #e5edf1;padding:7px;text-align:left}@media print{body{padding:0}.analytics-grid{break-inside:avoid}}</style></head><body><h1>Clínica Nova Salud</h1><div class="meta">${dashTabName(state.dashboardTab)} · ${dashPeriodLabel()} · ${dashBranch()}</div>${report.innerHTML}<script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close();
}
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-dash-tab]');if(tab){state.dashboardTab=tab.dataset.dashTab;renderDashboard($('#appContent'));return}
 const act=e.target.closest('[data-action]')?.dataset.action;
 if(act==='export-dashboard-excel'){exportCsv(`Nova_Salud_${state.dashboardTab}_${state.dashboardPeriod}.csv`,dashboardExportRowsV53());showToast('Reporte exportado en CSV compatible con Excel')}
 if(act==='print-dashboard'){printDashboardV53()}
});
;

