 const render=()=>renderInventory($('#appContent')),rows=v54MovementRows(),entries=rows.filter(x=>x.type==='ENTRADA').reduce((a,x)=>a+x.qty,0),sold=rows.filter(x=>x.type==='VENTA').reduce((a,x)=>a+x.qty,0),clinical=rows.filter(x=>x.type==='USO_CLINICO').reduce((a,x)=>a+x.qty,0),outs=rows.filter(x=>['SALIDA','VENTA','USO_CLINICO'].includes(x.type)).reduce((a,x)=>a+x.qty,0);
