 const crit=critical.slice().sort((a,b)=>(a.qty-a.min)-(b.qty-b.min)).slice(0,10).map(x=>[x.product,x.branch,x.warehouse,x.qty,x.min,x.expiry]);
 return `${dashKpis([{label:'Stock actual',value:stockUnits.toLocaleString('es-PE'),icon:'📦',sub:'Foto actual'},{label:'Unidades vendidas',value:sold.toLocaleString('es-PE'),icon:'🛒'},{label:'Unidades ingresadas',value:entered.toLocaleString('es-PE'),icon:'↓'},{label:'Uso clínico',value:used.toLocaleString('es-PE'),icon:'✚'},{label:'Venta estimada',value:money(saleValue),icon:'S/'}])}<div class="analysis-highlight"><b>Importante:</b> el stock es el estado actual. Los gráficos históricos sí obedecen al periodo seleccionado.</div><div class="analytics-grid"><div class="chart-card"><h3>Ventas de productos en el tiempo</h3><div class="chart-sub">Unidades con movimiento VENTA · ${dashPeriodLabel()}</div>${lineChart(trendBuckets(sales,x=>x.qty))}</div><div class="chart-card"><h3>Tipos de movimiento</h3><div class="chart-sub">Distribución de unidades</div>${donutChart(types,'unid.')}</div></div><div class="analytics-grid equal"><div class="chart-card"><h3>Productos más vendidos</h3><div class="chart-sub">Ranking según filtros</div>${hBars(top,{limit:10})}</div><div class="chart-card"><h3>${dashBranch()==='Todas las sedes'?'Stock actual por sede':'Stock actual por categoría'}</h3><div class="chart-sub">Existencia disponible</div>${hBars(stockGroup,{limit:8})}</div></div><div class="chart-card"><h3>Productos en nivel crítico</h3><div class="chart-sub">Prioridad para reposición</div>${dashTable(['Producto','Sede','Almacén','Stock','Mínimo','Vencimiento'],crit)}</div>`;
