 document.addEventListener('click',e=>{
   const act=e.target.closest('[data-action]')?.dataset.action;
   if(act==='new-emergency'){openEmergencyV60();return}
   if(act==='new-lab-order'){newLabOrderV60();return}
   const val=e.target.closest('[data-validation]');if(val){const action=val.dataset.validation,code=val.dataset.patientCode;let reason='';if(action==='observe')reason=prompt('¿Qué debe corregir o confirmar el paciente?','Verificar teléfono o dato de contacto.')||'';if(action==='reject')reason=prompt('Motivo del rechazo (solo si realmente no puede validarse):','Datos inconsistentes o solicitud no válida.')||'';if((action==='observe'||action==='reject')&&!reason)return;validatePatientV60(code,action,reason);renderValidationsV60($('#appContent'));return}
   const emgId=e.target.closest('[data-emg-identify]');if(emgId){const row=demo.emergencies.find(x=>x.code===emgId.dataset.emgIdentify);if(!row)return;const dni=(prompt('DNI identificado:','')||'').trim();if(!dni)return;let p=demo.patients.find(x=>x.dni===dni);if(!p){const name=(prompt('No existe en Nova Salud. Nombre completo para crear ficha mínima:','')||'').trim();if(!name)return;const code=nextCode('PAC',demo.patients,'code',20001);p={code,dni,name,phone:'',email:'',branch:row.branch,insurance:'Particular',status:'Activo',portalStatus:'Sin cuenta',registered:TODAY};demo.patients.push(p);addAudit('INSERT','paciente',code,'Paciente identificado desde emergencia')}row.patientCode=p.code;row.patient=p.name;row.dni=p.dni;row.identityStatus='Identificado';row.tempCode='';row.contactStatus=p.emergencyPhone?'Contacto disponible':'Por ubicar';addAudit('UPDATE','emergencia',row.code,'Identidad vinculada a '+p.code);showToast('Emergencia vinculada al paciente');renderEmergenciesV60($('#appContent'));return}
   const emgContact=e.target.closest('[data-emg-contact]');if(emgContact){const row=demo.emergencies.find(x=>x.code===emgContact.dataset.emgContact);if(row){row.contactStatus='Familiar informado';addAudit('UPDATE','emergencia',row.code,'Contacto familiar registrado');showToast('Contacto familiar registrado');renderEmergenciesV60($('#appContent'))}return}
   const emgNext=e.target.closest('[data-emg-next]');if(emgNext){const row=demo.emergencies.find(x=>x.code===emgNext.dataset.emgNext);if(row){const next={'Ingresado':'En evaluación','En evaluación':'En atención','En atención':'Observación','Observación':'Alta'};row.status=next[row.status]||row.status;addAudit('UPDATE','emergencia',row.code,'Estado: '+row.status);showToast('Estado de emergencia actualizado');renderEmergenciesV60($('#appContent'))}return}
   const nurse=e.target.closest('[data-nurse-complete]');if(nurse){const t=demo.nursingTasks.find(x=>x.code===nurse.dataset.nurseComplete);if(t){t.status='Completada';addAudit('UPDATE','tarea_enfermeria',t.code,'Tarea completada por '+state.user.name);showToast('Tarea marcada como completada');renderNurseDashboardV60($('#appContent'))}return}
   const lab=e.target.closest('[data-lab-step]');if(lab){const o=demo.labOrders.find(x=>x.code===lab.dataset.labCode);if(!o)return;if(lab.dataset.labStep==='sample')o.status='Muestra pendiente';if(lab.dataset.labStep==='process')o.status='En proceso';if(lab.dataset.labStep==='deliver'){o.status='Entregado';o.resultDate=o.resultDate||TODAY}if(lab.dataset.labStep==='ready'){const result=prompt('Resumen del resultado ficticio:','Dentro de rangos referenciales')||'Resultado disponible';o.status='Resultado listo';o.result=result;o.resultDate=TODAY;o.labTech=state.user.name;const p=demo.patients.find(x=>x.code===o.patientCode);if(p)notifyPatient(p,'Resultado de laboratorio disponible',`${o.test}: resultado disponible para revisión autorizada.`,'ok')}addAudit('UPDATE','orden_laboratorio',o.code,'Estado: '+o.status);showToast('Orden actualizada');renderLaboratoryV60($('#appContent'));return}
 });

